&reftitle.description;
boolftp_fput FTP\Connectionftp stringremote_filename resourcestream intmodeFTP_BINARY intoffset0
ftp_fput carica i dati da un puntatore al file in un file remoto sul server FTP.

&reftitle.changelog;





    &Version;
    &Description;



   &ftp.changelog.ftp-param;
   &ext.ftp.changelog.mode-valueerror;


    7.3.0

     Il parametro mode ora è opzionale. In precedenza era
     obbligatorio.

  &reftitle.examples;



    Esempio di ftp_fput


<?php

// apre un file in lettura
$file = 'somefile.txt';
$fp = fopen($file, 'r');

// stabilisce la connessione
$ftp = ftp_connect($ftp_server);

// si collega con nome utente e password
$login_result = ftp_login($ftp, $ftp_user_name, $ftp_user_pass);

// prova a caricare $file
if (ftp_fput($ftp, $file, $fp, FTP_ASCII)) {
    echo "$file caricato correttamente\n";
} else {
    echo "Si è verificato un problema durante il caricamento di $file\n";
}

// chiude la connessione e l'handle del file
ftp_close($ftp);
fclose($fp);

?>
